{
  "findings": [
    {
      "check_id": "CKV_GCP_49",
      "title": "Cloud Run service is publicly accessible",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "CRITICAL",
      "explanation": "The Cloud Run service is exposed to all users, potentially allowing unauthorized access to the service."
    }
  ],
  "patched_code": "resource \"google_cloud_run_service_iam_binding\" \"search_service_public\" {\n  location = google_cloud_run_service.search_service.location\n  project  = google_cloud_run_service.search_service.project\n  service  = google_cloud_run_service.search_service.name\n  role     = \"roles/run.invoker\"\n  members = [\n    \"user:specific-user@example.com\",\n  ]\n}",
  "fix_summary": "Replaced 'allUsers' with a specific user to restrict public access to the Cloud Run service."
}
